 (function ($) {
      "use strict";

      var defaults = {
        selector: ".item-point",
        styleSelector: "circle",
        animationSelector: "",
        animationPopoverIn: "fadeIn",
        animationPopoverOut: "fadeOut",
        onInit: null,
        getSelectorElement: null,
        getValueRemove: null
      };

      $.fn.scalize = function (options) {
        const settings = $.extend({}, defaults, options);

        return this.each(function () {
          const $scalize = $(this);
          const $points = $scalize.find(settings.selector);

          $scalize.css({ overflow: "visible" });
          $points.wrapAll("<div class='wrap-selector'></div>");

          if (settings.styleSelector) $points.addClass(settings.styleSelector);
          if (settings.animationSelector) {
            $points.addClass(settings.animationSelector);
            if (settings.animationSelector === "marker") {
              $points.append('<div class="pin"></div><div class="pulse"></div>');
            }
          }

          if (typeof settings.onInit === "function") settings.onInit();

          $scalize.find(".content").addClass("animated");

          $points.each(function () {
            const $point = $(this);
            const popoverSelector = $point.data("popover");
            const $popover = $scalize.find(popoverSelector);

            // Show/hide on click
            $point.on("click", function (e) {
              e.preventDefault();
              e.stopPropagation();

              const isActive = $point.hasClass("active");

              // Hide all other popovers
              $scalize.find(".item-point").removeClass("active");
              $scalize.find(".content")
                .stop(true, true)
               
                .removeClass("active " + settings.animationPopoverIn)
                .addClass(settings.animationPopoverOut);

              // Toggle current one
              if (!isActive) {
                $point.addClass("active");
                $popover
                  .stop(true, true)
                  .fadeIn()
                  .removeClass(settings.animationPopoverOut)
                  .addClass(settings.animationPopoverIn + " active");

                layout($scalize, settings);
              }
            });

            // Prevent clicks inside the popover from closing it
            $popover.on("click", function (e) {
              e.stopPropagation();
            });

            // Close button inside popover
            $popover.find(".exit").on("click", function (e) {
              e.preventDefault();
              e.stopPropagation();
              $point.removeClass("active");
              $popover
                .stop(true, true)
               
                .removeClass(settings.animationPopoverIn + " active")
                .addClass(settings.animationPopoverOut);
            });
          });

          // Click outside to close all popovers - Fixed implementation
          $(document).on("click.scalize", function (e) {
            // Only close if the click is outside the scalize container
            if ($(e.target).closest('.scalize-container').length === 0) {
              $scalize.find(".item-point").removeClass("active");
              $scalize.find(".content")
                .stop(true, true)
                .fadeOut()
                .removeClass(settings.animationPopoverIn + " active")
                .addClass(settings.animationPopoverOut);
            }
          });

          // Layout positioning
          function layout($container, settings) {
            const img = $container.find(".target").get(0);
            if (!img || !img.complete) return;

            const imageWidth = $(img).width();
            const imageHeight = $(img).height();
            const naturalWidth = img.naturalWidth;
            const naturalHeight = img.naturalHeight;

            const scaleX = imageWidth / naturalWidth;
            const scaleY = imageHeight / naturalHeight;

            $container.find(settings.selector).each(function () {
              const $point = $(this);
              const $popover = $container.find($point.data("popover"));

              let top = $point.data("top") * scaleY;
              let left = $point.data("left") * scaleX;

              $point.css({ top: `${top}px`, left: `${left}px` });

              const head = $popover.find(".head").outerHeight() || 0;
              const body = $popover.find(".body").outerHeight() || 0;
              const footer = $popover.find(".footer").outerHeight() || 0;
              const totalHeight = head + body + footer;

              $popover.css({ left: `${left}px`, height: `${totalHeight}px` });

              if ($popover.hasClass("bottom")) {
                $popover.css("top", `${top - $popover.outerHeight()}px`);
              } else if ($popover.hasClass("center")) {
                $popover.css("top", `${top - $popover.outerHeight() / 2}px`);
              } else {
                $popover.css("top", `${top}px`);
              }

              const $toggle = $point.find(".toggle");
              $toggle.css({ width: $point.outerWidth(), height: $point.outerHeight() });

              const $pin = $point.find(".pin");
              if ($pin.length) {
                $toggle.css({ width: $pin.outerWidth(), height: $pin.outerHeight() });
              }
            });
          }

          // Initial layout + responsive
          layout($scalize, settings);
          $(window).on("resize load", function () {
            layout($scalize, settings);
          });

          $scalize.find(".target").on("load", function () {
            layout($scalize, settings);
          });
        });
      };
    })(jQuery);

    // Initialize the plugin
    $(document).ready(function() {
      $('.scalize-container').scalize();
    });